def smallest_change(arr):
    def is_palindromic(sub_arr):
        return sub_arr == sub_arr[::-1]

    def count_changes(sub_arr):
        changes = 0
        left, right = 0, len(sub_arr) - 1
        while left < right:
            if sub_arr[left] != sub_arr[right]:
                changes += 1
            left += 1
            right -= 1
        return changes

    if not arr:
        return 0

    middle = len(arr) // 2
    left_sub_arr = arr[:middle]
    right_sub_arr = arr[middle + len(arr) % 2:]

    if is_palindromic(arr):
        return 0

